<?php declare(strict_types=1);
$ccPage=$ccState['page'];$ccFilters=$ccPage['filters']??[];foreach(['q'=>'','state'=>'active','attention'=>'','check_category'=>'']as$ccKey=>$ccDefault)if(!isset($ccFilters[$ccKey]))$ccFilters[$ccKey]=is_string($_GET[$ccKey]??null)?$_GET[$ccKey]:$ccDefault;
?>
<p><?= e($ccI('Datei, Zuständigkeit und nächste Frist an einem Ort. Fehlende oder fällige Nachweise findest du auch auf der Startseite.')) ?></p>
<form class="check-toolbar" method="get" data-check-filter><?= hidden('view','documents').hidden('tab','checks').hidden('state',$ccFilters['state']) ?>
<label><?= e($ccI('Nachweis suchen')) ?><input class="form-control" type="search" name="q" value="<?= e($ccFilters['q']) ?>" placeholder="<?= e($ccI('Titel oder Zuständigkeit')) ?>"></label>
<label><?= e($ccI('Kategorie')) ?><select class="form-control" name="check_category"><?php if($ccFilters['check_category']!==''&&!isset(\Kulturhus\Verein\DocumentChecks::CATEGORIES[$ccFilters['check_category']])):?><option value="<?= e($ccFilters['check_category']) ?>" selected><?= e($ccI('Kategorie prüfen')) ?></option><?php endif ?><option value=""><?= e($ccI('Alle Kategorien')) ?></option><?php foreach(\Kulturhus\Verein\DocumentChecks::CATEGORIES as$ccKey=>$ccLabel):?><option value="<?= e($ccKey) ?>" <?= $ccFilters['check_category']===$ccKey?'selected':'' ?>><?= e($ccI($ccLabel)) ?></option><?php endforeach ?></select></label>
<label><?= e($ccI('Welche Nachweise?')) ?><select class="form-control" name="attention"><option value=""><?= e($ccI('Alle anzeigen')) ?></option><option value="due" <?= $ccFilters['attention']==='due'?'selected':'' ?>><?= e($ccI('Fehlend oder fällig')) ?></option><?php if(!in_array($ccFilters['attention'],['','due'],true)):?><option value="<?= e($ccFilters['attention']) ?>" selected><?= e($ccI('Auswahl prüfen')) ?></option><?php endif ?></select></label>
<div class="actions"><button class="btn btn-outline theme-secondary dwf-button"><?= e($ccI('Suchen')) ?></button><a href="<?= e($ccUrl(['state'=>$ccFilters['state']])) ?>"><?= e($ccI('Suche zurücksetzen')) ?></a></div></form>
<?php $ccPager($ccPage,'check_page',$ccFilters); ?>
<?php if($ccPage!==null&&$ccPage['rows']): ?><div class="table-scroll"><table class="table check-list" data-check-original-list><thead><tr><th><?= e($ccI('Nachweis')) ?></th><th><?= e($ccI('Stand')) ?></th><th><?= e($ccI('Nächste Frist')) ?></th><th><?= e($ccI('Zuständig')) ?></th></tr></thead><tbody>
<?php foreach($ccPage['rows']as$ccRow):?><tr data-check-original-row data-check-alert="<?= $ccRow['status']['alert']?'1':'0' ?>"><td><a class="check-row-title" href="<?= e($ccUrl(['check'=>$ccRow['id']])) ?>"><?= e($ccRow['title']) ?></a><small><?= e($ccI(\Kulturhus\Verein\DocumentChecks::CATEGORIES[$ccRow['category']]??$ccRow['category'])) ?></small></td><td><span class="check-row-status"><?= e($ccI($ccRow['status']['label'])) ?></span></td><td data-label="<?= e($ccI('Nächste Frist')) ?>"><?= e($ccDate($ccRow['status']['due'])) ?></td><td data-label="<?= e($ccI('Zuständig')) ?>"><?= e($ccRow['responsible']!==''?$ccRow['responsible']:$ccI('Noch nicht zugeteilt')) ?></td></tr><?php endforeach ?>
</tbody></table></div><?php elseif($ccPage!==null): ?><p class="check-empty"><?= e($ccI('Keine passenden Nachweise. Ändere den Suchbegriff oder wähle „Alle anzeigen“.')) ?></p><?php endif ?>
<?php $ccPager($ccPage,'check_page',$ccFilters); ?>
